from pathlib import Path
import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
OUTPUTS = ROOT / "outputs"
REFERENCES = ROOT / "references"
REPORTS = ROOT / "validations/reports"

def validate_split_sizes_scaling():
    # Load the checks generated by part_b_regression.py
    checks = pd.read_csv(OUTPUTS / "part_b_checks.csv")

    # Convert the metric/value rows into a dictionary for easy lookup
    check_values = checks.set_index("metric")["value"].to_dict()

    # Acceptance criterion 1: exact split sizes
    expected_sizes = {
        "train_rows": 840,
        "val_rows": 180,
        "test_rows": 180,
    }

    for metric, expected in expected_sizes.items():
        actual = check_values[metric]

        assert actual == expected, (
            f"FAIL: {metric} expected {expected}, got {actual}"
        )

    print("PASS: Split sizes are exactly 840 / 180 / 180.")

    # Acceptance criterion 2: scaler fitting and transformation checks
    train_mean = check_values["train_scaled_max_abs_mean"]
    test_mean = check_values["test_scaled_max_abs_mean"]

    assert train_mean < 1e-9, (
        f"FAIL: train_scaled_max_abs_mean must be < 1e-9, got {train_mean}"
    )

    assert test_mean > 0.01, (
        f"FAIL: test_scaled_max_abs_mean must be > 0.01, got {test_mean}"
    )

    print("PASS: Training scaled mean is below 1e-9.")
    print("PASS: Test scaled mean is clearly non-zero (> 0.01).")

    print("All Part B split and scaling acceptance criteria passed.")

def validate_metrics():
    import numpy as np
    import pandas as pd

    METRICS_FILE = OUTPUTS / "part_b_metrics.csv"
    REFERENCE_FILE = REFERENCES / "part_b_reference_metrics.csv"

    # Load actual and reference metrics
    metrics = pd.read_csv(METRICS_FILE)
    reference = pd.read_csv(REFERENCE_FILE)

    # --------------------------------------------------
    # 1. Check the structure of part_b_metrics.csv
    # --------------------------------------------------

    expected_columns = ["model", "split", "MAE", "MSE", "RMSE", "R2"]

    assert list(metrics.columns) == expected_columns, (
        f"FAIL: Unexpected columns: {list(metrics.columns)}"
    )

    assert len(metrics) == 6, (
        f"FAIL: Expected 6 rows, found {len(metrics)}"
    )

    expected_validation_models = {
        "mean_baseline",
        "linear_regression",
        "decision_tree",
        "random_forest",
        "gradient_boosting",
    }

    validation_rows = metrics[metrics["split"] == "val"]
    test_rows = metrics[metrics["split"] == "test"]

    assert len(validation_rows) == 5, (
        f"FAIL: Expected 5 validation rows, found {len(validation_rows)}"
    )

    assert set(validation_rows["model"]) == expected_validation_models, (
        "FAIL: Validation rows do not contain exactly the five expected models"
    )

    assert len(test_rows) == 1, (
        f"FAIL: Expected exactly one test row, found {len(test_rows)}"
    )

    assert test_rows.iloc[0]["model"] in expected_validation_models, (
        "FAIL: The test row contains an unexpected model"
    )

    print("PASS: Six rows contain the five validation models and one test result.")

    # --------------------------------------------------
    # 2. Check RMSE = sqrt(MSE) for every row
    # --------------------------------------------------

    expected_rmse = np.sqrt(metrics["MSE"])

    rmse_matches = np.isclose(
        metrics["RMSE"],
        expected_rmse,
        atol=0.001,
        rtol=0
    )

    assert rmse_matches.all(), (
            "FAIL: RMSE does not match sqrt(MSE) for:\n"
            + metrics.loc[
                ~rmse_matches, ["model", "split", "MSE", "RMSE"]
            ].to_string(index=False)
    )

    print("PASS: Every RMSE matches sqrt(MSE) within 0.001.")

    # --------------------------------------------------
    # 3. Check reference R2 values and acceptance bands
    # --------------------------------------------------

    # Use the reference values supplied in the reference CSV.
    reference_lookup = reference.set_index("Item")["Reference"]

    reference_mapping = {
        "mean_baseline": "Baseline R² (validation)",
        "linear_regression": "Linear regression R² (validation)",
        "decision_tree": "Decision tree R² (validation)",
        "random_forest": "Random forest R² (validation)",
        "gradient_boosting": "Gradient boosting R² (validation)",
    }

    # Minimum/maximum R2 acceptance thresholds from the reference table.
    r2_bands = {
        "mean_baseline": (-0.10, 0.02),
        "linear_regression": (0.88, None),
        "decision_tree": (0.82, None),
        "random_forest": (0.86, None),
        "gradient_boosting": (0.88, None),
    }

    print("\nValidation R2 comparison with reference values:")

    for model_name, reference_item in reference_mapping.items():
        actual_row = validation_rows[
            validation_rows["model"] == model_name
            ]

        actual_r2 = float(actual_row.iloc[0]["R2"])
        reference_r2 = float(reference_lookup[reference_item])

        lower, upper = r2_bands[model_name]

        passed = (
                (lower is None or actual_r2 >= lower)
                and (upper is None or actual_r2 <= upper)
        )

        difference = actual_r2 - reference_r2
        status = "PASS" if passed else "FAIL"

        print(
            f"{status}: {model_name}: "
            f"actual R2={actual_r2:.4f}, "
            f"reference R2={reference_r2:.4f}, "
            f"difference={difference:+.4f}"
        )

        assert passed, (
            f"FAIL: {model_name} R2={actual_r2:.4f} "
            f"is outside the acceptance band [{lower}, {upper}]"
        )

    print("PASS: All five validation R2 acceptance bands are satisfied.")

    # --------------------------------------------------
    # 4. Check final test R2 against the reference
    # --------------------------------------------------

    test_row = test_rows.iloc[0]
    test_model = test_row["model"]
    test_r2 = float(test_row["R2"])

    reference_test_r2 = float(
        reference_lookup["Final model R² on test"]
    )

    test_r2_minimum = 0.88
    test_difference = test_r2 - reference_test_r2

    print("\nFinal test R2 comparison:")
    print(f"Selected model: {test_model}")
    print(f"Actual test R2: {test_r2:.4f}")
    print(f"Reference test R2: {reference_test_r2:.4f}")
    print(f"Difference: {test_difference:+.4f}")

    assert test_r2 >= test_r2_minimum, (
        f"FAIL: Test R2={test_r2:.4f} is below {test_r2_minimum}"
    )

    print("PASS: Final test R2 meets the minimum acceptance threshold.")

    # --------------------------------------------------
    # 5. Summary
    # --------------------------------------------------

    print("\nAll Part B metrics acceptance checks passed.")

def validate_tree_depth():
    tree_file = OUTPUTS / "part_b_tree_depth.csv"
    metrics_file = OUTPUTS / "part_b_metrics.csv"
    reference_file = REFERENCES / "part_b_reference_metrics.csv"

    tree_df = pd.read_csv(tree_file)
    metrics_df = pd.read_csv(metrics_file)
    reference_df = pd.read_csv(reference_file)

    # --------------------------------------------------
    # 1. Validate the eight tree-depth configurations
    # --------------------------------------------------

    expected_columns = ["max_depth", "train_rmse", "val_rmse"]

    assert list(tree_df.columns) == expected_columns, (
        f"FAIL: Unexpected columns: {list(tree_df.columns)}"
    )

    assert len(tree_df) == 8, (
        f"FAIL: Expected 8 tree-depth rows, found {len(tree_df)}"
    )

    assert tree_df["max_depth"].nunique() == 8, (
        "FAIL: Tree-depth configurations are duplicated"
    )

    print("PASS: Eight unique tree-depth configurations.")

    # Convert depths into sortable numeric values.
    # Unlimited depth is treated as greater than finite depths.
    depth_labels = tree_df["max_depth"].astype(str).str.strip()

    numeric_depths = depth_labels.map(
        lambda depth: (
            float("inf")
            if depth.lower() == "unlimited"
            else float(depth)
        )
    )

    ordered = (
        tree_df.assign(_depth=numeric_depths)
        .sort_values("_depth")
    )

    # --------------------------------------------------
    # 2. Training RMSE must not increase with depth
    # --------------------------------------------------

    train_rmse_diff = ordered["train_rmse"].diff().dropna()

    assert (train_rmse_diff <= 0.001).all(), (
        "FAIL: Training RMSE increases as tree depth grows."
    )

    print("PASS: Training RMSE never increases as depth grows.")

    # --------------------------------------------------
    # 3. Read and parse reference values
    # --------------------------------------------------

    reference_lookup = reference_df.set_index("Item")["Reference"]

    # The reference contains both depth and RMSE, e.g. "6 / 6.28".
    reference_best = str(
        reference_lookup["Best tree depth / its val_rmse"]
    ).strip().strip("'\"")

    try:
        reference_best_depth, reference_best_val_rmse = [
            float(value.strip())
            for value in reference_best.split("/")
        ]
    except (ValueError, TypeError):
        raise AssertionError(
            "FAIL: Could not parse the reference entry "
            f"'Best tree depth / its val_rmse': {reference_best!r}. "
            "Expected a value such as '6 / 6.28'."
        )

    # --------------------------------------------------
    # 4. Validate the best depth and validation RMSE
    # --------------------------------------------------

    best_row = tree_df.loc[tree_df["val_rmse"].idxmin()]
    best_depth = str(best_row["max_depth"]).strip()
    best_val_rmse = float(best_row["val_rmse"])

    # Acceptance criterion: best depth is >= 4 or unlimited.
    assert (
        best_depth.lower() == "unlimited"
        or float(best_depth) >= 4
    ), (
        f"FAIL: Best depth is {best_depth}; "
        "expected depth >= 4 or unlimited."
    )

    print(
        f"PASS: Best depth is {best_depth}; "
        f"lowest validation RMSE = {best_val_rmse:.4f}."
    )

    # Compare the observed best depth with the reference depth.
    # The reference depth is a benchmark; the acceptance band
    # allows any depth >= 4 or unlimited.
    if best_depth.lower() != "unlimited":
        assert float(best_depth) == reference_best_depth, (
            f"FAIL: Best depth {best_depth} differs from "
            f"reference depth {reference_best_depth:.0f}."
        )

    # Allow a 0.50 RMSE difference from the reference value.
    assert abs(
        best_val_rmse - reference_best_val_rmse
    ) <= 0.50, (
        f"FAIL: Best validation RMSE {best_val_rmse:.4f} differs "
        f"from reference {reference_best_val_rmse:.4f} "
        "by more than 0.50."
    )

    print(
        f"PASS: Best validation RMSE is within 0.50 of "
        f"reference {reference_best_val_rmse:.2f}."
    )

    # --------------------------------------------------
    # 5. Depth 1: high-bias acceptance checks
    # --------------------------------------------------

    depth_1_rows = tree_df[depth_labels == "1"]

    assert len(depth_1_rows) == 1, (
        "FAIL: Expected exactly one depth-1 row."
    )

    depth_1 = depth_1_rows.iloc[0]

    depth_1_train_rmse = float(depth_1["train_rmse"])
    depth_1_val_rmse = float(depth_1["val_rmse"])

    depth_1_gap = depth_1_val_rmse - depth_1_train_rmse
    depth_1_difference = depth_1_val_rmse - best_val_rmse

    assert depth_1_gap <= 2.5, (
        f"FAIL: Depth-1 validation-minus-training RMSE gap "
        f"is {depth_1_gap:.4f}; expected <= 2.5."
    )

    assert depth_1_difference >= 4.0, (
        f"FAIL: Depth-1 validation RMSE exceeds the best by "
        f"{depth_1_difference:.4f}; expected >= 4.0."
    )

    print(
        f"PASS: Depth-1 RMSE gap = {depth_1_gap:.4f} (<= 2.5)."
    )
    print(
        f"PASS: Depth-1 RMSE exceeds the best by "
        f"{depth_1_difference:.4f} (>= 4.0)."
    )

    # --------------------------------------------------
    # 6. Unlimited depth: high-variance acceptance checks
    # --------------------------------------------------

    unlimited_rows = tree_df[
        depth_labels.str.lower() == "unlimited"
    ]

    assert len(unlimited_rows) == 1, (
        "FAIL: Expected exactly one unlimited-depth row."
    )

    unlimited = unlimited_rows.iloc[0]

    unlimited_train_rmse = float(unlimited["train_rmse"])
    unlimited_val_rmse = float(unlimited["val_rmse"])
    unlimited_gap = unlimited_val_rmse - unlimited_train_rmse

    assert unlimited_train_rmse <= 0.01, (
        f"FAIL: Unlimited-depth training RMSE is "
        f"{unlimited_train_rmse:.4f}; expected approximately 0."
    )

    assert unlimited_gap >= 5.0, (
        f"FAIL: Unlimited-depth RMSE gap is {unlimited_gap:.4f}; "
        "expected >= 5.0."
    )

    print(
        f"PASS: Unlimited-depth training RMSE = "
        f"{unlimited_train_rmse:.4f} (approximately 0)."
    )
    print(
        f"PASS: Unlimited-depth RMSE gap = "
        f"{unlimited_gap:.4f} (>= 5.0)."
    )

    # --------------------------------------------------
    # 7. Decision-tree metrics must match the best depth
    # --------------------------------------------------

    decision_tree_rows = metrics_df[
        (metrics_df["model"] == "decision_tree")
        & (metrics_df["split"] == "val")
    ]

    assert len(decision_tree_rows) == 1, (
        "FAIL: Expected exactly one decision_tree validation row."
    )

    decision_tree_rmse = float(
        decision_tree_rows.iloc[0]["RMSE"]
    )

    assert abs(
        decision_tree_rmse - best_val_rmse
    ) <= 0.001, (
        f"FAIL: decision_tree validation RMSE "
        f"{decision_tree_rmse:.4f} does not match the lowest "
        f"tree-depth validation RMSE {best_val_rmse:.4f} "
        "within 0.001."
    )

    print(
        f"PASS: Decision-tree validation RMSE "
        f"{decision_tree_rmse:.4f} matches the best depth "
        f"RMSE {best_val_rmse:.4f} within 0.001."
    )

    print("All tree-depth acceptance criteria passed.")

def validate_gb_learning_rate():
    file_path = OUTPUTS / "part_b_gb_learning_rate.csv"
    reference_path = REFERENCES / "part_b_reference_metrics.csv"

    gb_df = pd.read_csv(file_path)
    reference_df = pd.read_csv(reference_path)

    # 1. Check the expected columns and number of rows
    expected_columns = ["learning_rate", "val_rmse", "val_r2"]

    assert list(gb_df.columns) == expected_columns, (
        f"FAIL: Expected columns {expected_columns}, "
        f"found {list(gb_df.columns)}"
    )

    assert len(gb_df) == 3, (
        f"FAIL: Expected 3 learning-rate rows, found {len(gb_df)}"
    )

    assert gb_df["learning_rate"].nunique() == 3, (
        "FAIL: Learning-rate values are duplicated"
    )

    expected_rates = {0.01, 0.1, 1.0}

    actual_rates = set(gb_df["learning_rate"].astype(float))

    assert actual_rates == expected_rates, (
        f"FAIL: Expected learning rates {expected_rates}, "
        f"found {actual_rates}"
    )

    print("PASS: Three unique learning-rate configurations.")

    # 2. Extract validation R2 scores
    r2_by_rate = gb_df.set_index("learning_rate")["val_r2"]

    r2_001 = float(r2_by_rate.loc[0.01])
    r2_01 = float(r2_by_rate.loc[0.1])
    r2_1 = float(r2_by_rate.loc[1.0])

    # 3. Check the required ranking
    assert r2_01 > r2_1 > r2_001, (
        "FAIL: Expected R²(0.1) > R²(1.0) > R²(0.01), "
        f"but got {r2_01:.4f}, {r2_1:.4f}, {r2_001:.4f}"
    )

    print("PASS: R²(0.1) > R²(1.0) > R²(0.01).")

    # 4. Load the reference thresholds
    reference_lookup = reference_df.set_index("Item")["Reference"]

    # The combined reference entry is "0.713 / 0.931 / 0.844".
    reference_r2_values = [
        float(value.strip())
        for value in str(
            reference_lookup[
                "Learning rate 0.01 / 0.1 / 1.0: validation R²"
            ]
        ).split("/")
    ]

    reference_r2_001, reference_r2_01, reference_r2_1 = (
        reference_r2_values
    )

    # Report actual vs reference values
    print("\nLearning-rate R² comparison:")
    print(
        f"0.01: actual={r2_001:.4f}, "
        f"reference={reference_r2_001:.3f}"
    )
    print(
        f"0.1:  actual={r2_01:.4f}, "
        f"reference={reference_r2_01:.3f}"
    )
    print(
        f"1.0:  actual={r2_1:.4f}, "
        f"reference={reference_r2_1:.3f}"
    )

    # 5. Check the specified acceptance thresholds
    assert r2_01 >= 0.90, (
        f"FAIL: R²(0.1) = {r2_01:.4f}; expected >= 0.90"
    )

    assert r2_001 <= 0.80, (
        f"FAIL: R²(0.01) = {r2_001:.4f}; expected <= 0.80"
    )

    print("PASS: R²(0.1) >= 0.90.")
    print("PASS: R²(0.01) <= 0.80.")
    print("All gradient-boosting learning-rate checks passed.")

def validate_part_b_cv():
    cv_file = OUTPUTS / "part_b_cv.csv"
    reference_file = REFERENCES / "part_b_reference_metrics.csv"

    cv_df = pd.read_csv(cv_file)
    reference_df = pd.read_csv(reference_file)

    # 1. Check columns and row count
    expected_columns = ["model", "mean_r2", "std_r2"]

    assert list(cv_df.columns) == expected_columns, (
        f"FAIL: Expected columns {expected_columns}, "
        f"found {list(cv_df.columns)}"
    )

    assert len(cv_df) == 2, (
        f"FAIL: Expected 2 cross-validation rows, found {len(cv_df)}"
    )

    assert cv_df["model"].nunique() == 2, (
        "FAIL: The two cross-validation rows must represent "
        "two distinct models"
    )

    assert cv_df["model"].notna().all(), (
        "FAIL: A model name is missing"
    )

    assert cv_df[["mean_r2", "std_r2"]].notna().all().all(), (
        "FAIL: Cross-validation metrics contain missing values"
    )

    print("PASS: part_b_cv.csv contains two distinct model rows.")

    # 2. Check the reference acceptance criteria
    assert (cv_df["mean_r2"] >= 0.90).all(), (
        "FAIL: At least one model has mean CV R² below 0.90"
    )

    assert (cv_df["std_r2"] <= 0.03).all(), (
        "FAIL: At least one model has CV R² standard deviation above 0.03"
    )

    print("PASS: Both models have mean CV R² >= 0.90.")
    print("PASS: Both models have CV R² standard deviation <= 0.03.")

    # 3. Display results for review
    print("\nCross-validation results:")
    print(cv_df.to_string(index=False))

    print("\nCode review requirement:")
    print(
        "Confirm in part_b_regression.py that one KFold object is "
        "created outside the model loop and passed to every "
        "cross_val_score() call."
    )

    print("All Part B cross-validation output checks passed.")

if __name__ == "__main__":
    validate_split_sizes_scaling()
    validate_metrics()
    validate_tree_depth()
    validate_gb_learning_rate()
    validate_part_b_cv()